namespace ChessGame.Api.Online;

// Presentation copy follows the pinned match rules; v3 matches the Unity practice catalog.
public sealed record ChaosBuffDefinition(int Id, string Tier, string DisplayName, string Description, string? Summary = null);

public static class ChaosBuffCatalog
{
    public static IReadOnlyList<ChaosBuffDefinition> LegacyDefinitions { get; } = Array.AsReadOnly(new ChaosBuffDefinition[]
    {
        new(0, "Silver", "Commandant Pawn", "Before play, choose three allied Pawns, or all remaining Pawns if fewer than three survive. Those Pawns may advance two squares on a clear file throughout the match. Both squares must be empty; the advance cannot capture or jump.", "Three chosen Pawns gain a repeatable two-square advance on clear files."),
        new(1, "Silver", "Strong Fortress", "Castle from the King's original back-rank file with a clear path and a safe final square. This buff permits exactly one otherwise disqualifying condition: the King has moved, the Rook has moved, the King is in check, or the King crosses an attacked square. Two or more such conditions still prevent castling.", "Castling may ignore one restriction, while keeping a clear path and a safe destination."),
        new(2, "Silver", "Freestyle Leap", "All your Knights may land on intermediate squares along their L-shaped routes. They still jump over pieces. A two-by-two diagonal is excluded, and your own King must remain safe.", "Your Knights can land on intermediate squares along their L-shaped leaps."),
        new(3, "Gold", "Doppelganger", "Before play, choose an allied Knight and Bishop. Their movement is exchanged. The first toggle becomes available after five of your completed turns; later toggles have a five-owner-turn cooldown. Both chosen pieces must still exist, and the toggle must leave your King safe.", "Exchange a Knight and Bishop's movement; toggle the swap every five owner turns."),
        new(4, "Gold", "Suicide Bomber", "Once per match, the capture of your original Queen detonates a three-by-three area centered on her square. All non-King pieces in that area are removed, including allies and the capturer. Promoted Queens do not trigger the explosion.", "Your original Queen explodes once when captured, destroying nearby non-Kings."),
        new(5, "Diamond", "Flying Thunder God", "Your original Queen may teleport to any empty active square as her move, provided your King stays safe. You have five teleports in the match. Each use recharges after five of your completed turns. Promoted Queens cannot teleport.", "Teleport your original Queen to an empty square. Five uses, five-turn recharge."),
        new(6, "Silver", "Noble Sacrifice", "A Pawn may capture an allied Pawn diagonally ahead and gain Bloodthirsty. The empowered Pawn may move or capture into any of the three squares immediately ahead, and may also retreat one empty square. Your King must remain safe.", "Sacrifice an allied Pawn to empower the capturing Pawn with Bloodthirsty."),
        new(7, "Silver", "Absolute Sniper", "A Bishop that captures an enemy non-Pawn from at least four diagonal squares away gains a Snipe charge for its next five owner turns. Use Snipe by selecting that Bishop and then an enemy non-King on a clear diagonal. The victim is captured without moving the Bishop, consuming the charge and your turn.", "Long Bishop captures charge a ranged Snipe that does not move the Bishop."),
        new(8, "Silver", "Gambling Leads to Misery", "When a Pawn captures an enemy, there is a 30% chance to keep the turn for an immediate extra move with that same Pawn. The Pawn must have a legal follow-up move. At most two extra moves can be awarded to your side in a match.", "Pawn captures may grant an extra move with that Pawn, up to twice per match."),
        new(9, "Silver", "Loot Box", "At rounds 25 and 50, a crate appears on an empty active square. Collect your own crate to deploy a Rook at 25 or a Queen at 50 onto an empty square in your half. An enemy landing on your crate destroys it instead. Deployment resolves before ordinary play continues.", "Crates arrive at rounds 25 and 50. Collect them to deploy a Rook, then a Queen."),
        new(10, "Gold", "Peace T-Shirt", "Keep your King out of check during the first fifteen of your turns. Once you have completed fifteen turns without failing that condition, use Recruit once: choose an enemy other than a King or Queen, then an empty square in your first three ranks. The recruitment must leave your King safe.", "Avoid early checks to unlock a one-time recruitment into your first three ranks."),
        new(11, "Gold", "Rise of Pawn", "All your Pawns may retreat one square into an empty square. A Pawn retreating onto its own back rank is removed and leaves a mine. An enemy that later lands on the mine is removed and consumes it; your own pieces do not trigger it.", "Retreat Pawns onto your back rank to turn them into enemy-triggered mines."),
        new(12, "Gold", "Mobile Fortress", "Use Load Pawn to select an allied Rook, then an allied Pawn. The Pawn is removed and stored in the Rook; a Rook can carry only one passenger. If that carrier is destroyed, deploy its passenger onto a nearby empty square within the surrounding three-by-three region. A Pawn deployed on its far rank becomes a Queen.", "A Rook carries a Pawn and releases it for deployment when the carrier is destroyed."),
        new(13, "Gold", "Hiding King", "Use Hide King on your turn to exchange your King with another allied piece on your back rank. Both pieces count as moved and the King must end safe. The ability recharges after ten of your completed turns.", "Swap your King with a back-rank ally, with a ten-owner-turn cooldown."),
        new(14, "Gold", "Gacha Banner", "Enemy captures grant combat tickets: one for a Pawn, three for a Queen, two for another piece. Spend one ticket to summon a random ally onto a random empty active square, at most twice per owner turn. Chances: Pawn 70%, Knight 10%, Bishop 10%, Rook 9%, Queen 1%.", "Capture pieces for tickets. Spend one to summon an ally, at most twice per turn."),
        new(15, "Diamond", "Substitute Ninjutsu", "The first time your King starts a turn in check, teleport it to a random safe empty square in your half, if one is available. A decoy is left on the original square. It moves like a King and transforms into the first enemy type it captures. This protection activates once.", "Your first check teleports your King to safety and leaves a transforming decoy."),
        new(16, "Diamond", "High-Tech Era", "Your original Rooks begin with cannon charges. A charged Rook retains normal movement and can also capture straight across exactly one blocking piece. An unused initial charge expires after ten owner turns; a cannon capture refreshes that Rook's charge for ten more owner turns.", "Your original Rooks can capture across exactly one blocker while charged."),
        new(17, "Diamond", "Queen's Betrayal", "Gain an extra Queen on an empty square of your third rank. At the end of each owner turn, this unstable Queen has a 10% chance to change sides on her current square. Her instability continues under her new owner, so later betrayals remain possible.", "Gain an extra Queen, with a 10% chance to betray her owner each owner turn."),
        new(18, "Diamond", "Definition of CHAOS", "At round 10, the outermost file on each side of the board collapses and its pieces are removed. At round 15, the next pair collapses, leaving a four-by-eight board. Collapsed squares can no longer be entered; mines and crates on them are removed too.", "Outer files collapse at rounds 10 and 15. Move your army toward the center."),
        new(19, "Diamond", "RNG Fiesta", "At setup, every one of your pieces other than Kings and Queens is independently transformed into a random Pawn, Knight, Bishop or Rook. Their squares are preserved and the transformed pieces count as moved. The server resolves all random outcomes.", "Randomize your starting army, keeping Kings and Queens unchanged."),
        new(20, "Diamond", "I-Frame Roll", "If you would be checkmated, choose a safe empty active square within two files and two ranks of your King. Escape to that square without spending an ordinary move. You may escape up to three times in a match, and only if a safe destination exists.", "Escape checkmate by moving the King to nearby safety, at most three times."),
        new(21, "Legendary", "Ghost Army", "Your sliding pieces can pass through allied blockers when moving or capturing, but enemies still block their paths and you cannot land on an ally. Initial Pawn double advances may also pass through an ally. Phasing through a blocker cannot be used as an attack to give check.", "Pass through allies when moving; this phasing cannot be used to give check."),
        new(22, "Legendary", "Plague Town", "An enemy that captures one of your pieces becomes infected. It is removed after its next four completed owner turns. The infection belongs to the capturing piece and does not require another action from you.", "Enemies capturing your pieces become infected and die after four owner turns."),
        new(23, "Legendary", "Customize Army", "During setup, rearrange every piece inside your own half and confirm within 120 seconds. Every piece needs a distinct active square and your King must be safe. Keeping the original formation, including letting the timer expire unchanged, replaces this buff with a random Gold buff; any required follow-up setup must still be completed.", "Rearrange your army within two minutes, or trade an unchanged formation for Gold."),
        new(24, "Legendary", "Pawns' Revolution", "At setup, remove all your pieces except the King. Fill every empty active square in your half of the board with allied Pawns. Play then continues with this new army under the normal safety and promotion rules.", "Trade your non-King army for Pawns filling your half of the board."),
        new(25, "Legendary", "One-Man Army", "At setup, remove every piece except your King. Your King gains two-square straight moves with a clear path, and starts with a rifle charge. Aim for at most fifteen seconds and fire once: only an enemy non-King, non-Queen hit can be removed. A shot or aim timeout recharges after three of your completed turns. Exiting aim without firing keeps the charge; firing does not replace your ordinary move.", "Keep only an empowered King and a rifle that recharges every three owner turns.")
    });

    public static IReadOnlyList<ChaosBuffDefinition> ForRules(int version) => version == 3 ? Definitions : LegacyDefinitions;

